module.exports.compileValidate = compileValidate
module.exports.resolveProjectRoot = resolveProjectRoot
module.exports.categorize = categorize
module.exports.MpxCliNotFoundError = MpxCliNotFoundError
module.exports.InvalidInputError = InvalidInputError

if (require.main === module) {
  runCli().catch(err => {
    if (err instanceof MpxCliNotFoundError || err instanceof InvalidInputError) {
      console.error(`${err.name}: ${err.message}`)
    } else {
      console.error(err && err.stack ? err.stack : err)
    }
    process.exit(2)
  })
}

async function runCli () {
  const argv = process.argv.slice(2)
  const files = []
  let targetArg = 'web'
  let typeArg = 'component'
  let jsonOut = false
  let ignoreSubComponents = true
  let projectRoot

  for (const a of argv) {
    if (a === '-h' || a === '--help') {
      printHelp()
      process.exit(0)
    } else if (a.startsWith('--target=')) {
      targetArg = a.slice('--target='.length)
    } else if (a.startsWith('--type=')) {
      typeArg = a.slice('--type='.length)
    } else if (a.startsWith('--project-root=')) {
      projectRoot = a.slice('--project-root='.length)
    } else if (a === '--json') {
      jsonOut = true
    } else if (a === '--no-ignore-sub-components') {
      ignoreSubComponents = false
    } else if (a.startsWith('-')) {
      console.error(`未知参数: ${a}`); process.exit(2)
    } else {
      files.push(a)
    }
  }
  if (!files.length) { printHelp(); process.exit(2) }

  const target = targetArg.includes(',') ? targetArg.split(',') : targetArg
  const startedAt = Date.now()
  const outputCapture = jsonOut ? captureOutput() : null
  const originalExit = process.exit
  let exitIntercepted = false
  if (jsonOut) {
    process.exit = function (code) {
      const error = new Error(`Compile dependency requested process exit ${code}`)
      error.name = 'InterceptedProcessExit'
      error.exitCode = code
      throw error
    }
    exitIntercepted = true
  }
  let result
  try {
    result = await compileValidate(files, {
      target, type: typeArg, ignoreSubComponents, projectRoot
    })
  } catch (err) {
    const captured = outputCapture ? outputCapture.restore() : { stdout: '', stderr: '' }
    if (exitIntercepted) process.exit = originalExit
    const details = [
      captured.stderr.trim(),
      captured.stdout.trim(),
      err && err.stack ? err.stack : String(err)
    ].filter(Boolean).join('\n')
    if (!jsonOut) throw err
    result = {
      success: false,
      target: targetArg,
      projectRoot: projectRoot ? path.resolve(projectRoot) : null,
      errors: [{
        category: 'configuration',
        message: truncate(details || 'Mpx compile initialization failed', 20),
        raw: details || 'Mpx compile initialization failed'
      }],
      warnings: [],
      summary: { total: 1, byCategory: { configuration: 1 } },
      durationMs: Date.now() - startedAt
    }
  } finally {
    if (outputCapture) outputCapture.restore()
    if (exitIntercepted) process.exit = originalExit
  }

  if (jsonOut) {
    console.log(JSON.stringify(result, null, 2))
  } else {
    prettyPrint(result)
  }
  process.exit(isSuccess(result) ? 0 : 1)
}

function captureOutput () {
  const stdoutWrite = process.stdout.write
  const stderrWrite = process.stderr.write
  const stdout = []
  const stderr = []
  let active = true
  process.stdout.write = function (chunk, encoding, callback) {
    stdout.push(String(chunk))
    if (typeof encoding === 'function') encoding()
    if (typeof callback === 'function') callback()
    return true
  }
  process.stderr.write = function (chunk, encoding, callback) {
    stderr.push(String(chunk))
    if (typeof encoding === 'function') encoding()
    if (typeof callback === 'function') callback()
    return true
  }
  return {
    restore () {
      if (active) {
        process.stdout.write = stdoutWrite
        process.stderr.write = stderrWrite
        active = false
      }
      return { stdout: stdout.join(''), stderr: stderr.join('') }
    }
  }
}

function printHelp () {
  console.log(`usage: compile-validate <file.mpx>... [options]

options:
  --target=<mode>              编译目标 (默认 web)，多个用逗号分隔
  --type=<page|component>      入口类型，默认 component
  --project-root=<path>        显式指定宿主项目根目录（覆盖自动探测）
  --no-ignore-sub-components   不忽略子组件，一并纳入编译
  --json                       输出结构化 JSON
  -h, --help                   查看帮助`)
}

function isSuccess (result) {
  if (!result) return true
  if (typeof result.success === 'boolean') return result.success
  return Object.values(result).every(r => r && r.success)
}

function prettyPrint (result) {
  if (result && typeof result.success === 'boolean') { prettyPrintOne(result); return }
  for (const [t, r] of Object.entries(result)) {
    console.log(`\n=== target=${t} ===`)
    prettyPrintOne(r)
  }
}

function prettyPrintOne (r) {
  console.log(`target: ${r.target}  success: ${r.success}  duration: ${r.durationMs}ms`)
  console.log(`errors: ${r.errors.length}  warnings: ${r.warnings.length}`)
  if (r.summary.total > 0) {
    const pairs = Object.entries(r.summary.byCategory)
      .map(([k, v]) => `${k}=${v}`).join(', ')
    console.log(`by category: ${pairs}`)
  }
  r.errors.forEach((e, i) => {
    const locStr = e.loc ? `:${e.loc.line}:${e.loc.column}` : ''
    const fileStr = e.file ? ` ${e.file}${locStr}` : ''
    console.log(`\n[${i + 1}][${e.category}${e.block ? '/' + e.block : ''}]${fileStr}`)
    console.log(e.message)
  })
}

